<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Payment receipt</title>
<style>@page{margin:35px}body{font-family:DejaVu Sans,sans-serif;color:#1f2937;font-size:11px}h1{font-size:22px;margin:0 0 4px}.muted{color:#6b7280}table{width:100%;border-collapse:collapse;margin-top:18px}td{padding:8px 4px;border-bottom:1px solid #d1d5db}td:first-child{width:35%;color:#6b7280}.amount{font-size:18px;font-weight:bold;color:#111827}</style></head><body>
<h1>Payment receipt</h1><div class="muted">Payment #{{ $payment->id }} · Generated {{ now()->format('d M Y H:i') }}</div>
<table><tr><td>Customer</td><td>{{ $payment->user?->name }} ({{ $payment->user?->email }})</td></tr><tr><td>Payment status</td><td>{{ ucfirst(str_replace('_', ' ', $payment->status)) }}</td></tr><tr><td>Payment method</td><td>{{ ucfirst($payment->gateway) }}</td></tr><tr><td>Gateway reference</td><td>{{ $payment->gateway_reference ?? '—' }}</td></tr><tr><td>Payment date</td><td>{{ $payment->created_at?->format('d M Y H:i') }}</td></tr><tr><td>Amount</td><td class="amount">{{ $payment->currency }} {{ number_format($payment->amount_cents / 100, 2) }}</td></tr></table>
@if($payment->refunds->isNotEmpty())<h3>Refunds</h3><table>@foreach($payment->refunds as $refund)<tr><td>{{ $refund->created_at?->format('d M Y H:i') }}</td><td>{{ ucfirst($refund->status) }} · {{ $refund->currency }} {{ number_format($refund->amount_cents / 100, 2) }}</td></tr>@endforeach</table>@endif
</body></html>
